-- ========================================================
-- DDL TABLE CHART OF ACCOUNTS (KODE AKUN SIPD / BELANJA DAERAH)
-- Project: BOK SIPPINTER (bok.sippinter.com)
-- ========================================================

CREATE TABLE IF NOT EXISTS `chart_of_accounts` (
  `id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `kode_akun` VARCHAR(50) NOT NULL COMMENT 'Kode Rekening Akun SIPD (misal: 5.1.02.01.001.00001)',
  `nama_akun` VARCHAR(255) NOT NULL COMMENT 'Deskripsi/Nama Akun Belanja',
  `kategori` VARCHAR(100) NOT NULL DEFAULT 'Belanja Daerah',
  `level` TINYINT(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Tingkat kedalaman hierarki kode rekening (1-6)',
  `parent_kode` VARCHAR(50) DEFAULT NULL COMMENT 'Kode rekening induk/parent',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = Aktif, 0 = Nonaktif',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_coa_kode_akun` (`kode_akun`),
  KEY `idx_coa_parent_kode` (`parent_kode`),
  KEY `idx_coa_kategori` (`kategori`),
  KEY `idx_coa_level` (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE `nama_akun` = VALUES(`nama_akun`), `kategori` = VALUES(`kategori`);

